const SUIT_TEXTS = {"Бубны":"Бубны ақшаны бейнелейді. Осы мастьта (мастью) туған адамдар бұл әлемге (әрқайсысы әртүрлі) ақшаға, материалдық құндылықтарға дұрыс қарауды үйрену үшін келген. Бубны — қаржы мен құндылықтар мастьі, — кемелдену және мансаптық жетістіктер кезеңі, күз. Стихиясы — Жер, Тародағы Пентакльдер мастьі.\nБубны мастьі қабылдағыштықты, іскерлікті, ақшаны және бағалау қабілетін бейнелейді. Масттың жоғары дамыған өкілдерінде бұл қабілеттер материалдық саладан шығып, рухани құндылықтар мен жеке қасиеттерге таралады. Аз дамыған адамның сипаттамасында Бубны қаржылық мүдделерді көрсетеді.\nБубны сөздің кең мағынасында құндылықтармен тығыз байланысты және бұл өмірде неге назар аударуға тұрарлық, неге тұрарлық емес екенін үнемі анықтауға ұмтылады. Олар үшін дүниедегі бәрінің өз бағасы бар және белгілі бір дәрежеде өздерін құндылықтарымен және мүлкімен теңестіреді. Бубны бала кезінен-ақ қалағанына жететін әдістерді қалыптастырады. Олардың өмірлік философиясы адам сыйақы алу немесе жазадан құтылу үшін бәріне барады деген ойға негізделген.\nКөңіл күйі нашар болғанда Бубны мастьінің өкілі әдетте сауда жасауға барады, сөйтіп көрген өкпесінің орнын толтырғандай болады. Алайда Бубны тым ойсыз әрі мол шығын жасауға бейім. Оның үстіне олар сатып алатын заттардың сапасын есте сақтауы керек. Сапасыз бір нәрсе сатып алса, бұл арқылы өздеріне басқа кез келген масть өкілдеріне қарағанда әлдеқайда көп зиян келтіреді. Екінші жағынан, сапаға ұмтылу көбірек шығынды да білдіреді, бұл Бубнаны ақшаның жетіспеуінен үнемі уайымдататын тұйық шеңберге айналуы мүмкін.\nБубны мастьінің өкілдері — әлемдегі ең жақсы саудагерлер; оларда басқа адамдарды қандай да бір заттың құндылығына сендірудің ерекше қабілеті бар. Біз кездесетін жарнаманың едәуір бөлігін Бубны мастьінің өкілдері жасайды. Сатушылардың арасында да Бубны немесе Өмірлік жиынтығында (Жизненный Набор) бубны карталары көп адамдар көп. Қандай да бір тауардың құндылығы мен сапасына сенген Бубна оны жарнамалау үшін бәріне барады.\nБубны мастьіне жататын адамдардың көпшілігі өздерінің материалдық мүмкіндіктерін объективті бағалайды, бұл сәттіліктің кепілі. Бұл қасиет Бубнаға өзінің немесе басқалардың қабілеттері мен таланттарын нақты ақшаға айналдыруға көмектеседі. Ең маңыздысы — ол оларға өмірді түсінудің тұрақты ішкі жүйесін береді. Өз құндылықтарын нақты сезінетін Бубны ешқашан бөтен ақиқаттың, философияның ықпалына немесе эмоциялық факторлардың әсеріне түспейді. Әрбір жаңа тәжірибе мен жаңа ақпаратты Бубны практикалық пайда алу тұрғысынан бағалайды. Бір қарағанда мұндай бағалау жүйесі тек табыс табу немесе материалдық тұрақтылыққа жету үшін пайдаланылатындай көрінуі мүмкін, бірақ түптеп келгенде бұл қасиеттер Бубнаға оларды не бақытты ететінін түсінуге көмектеседі.\nБарлық Бубны ерте ме, кеш пе ақша мен мүлік табуды өмірінің басты мақсатына айналдырады. Соның арқасында олар өздерін жақсырақ түсінуге мүмкіндік алады. Қалаған «көп ақшаны» тапқан соң, бұл мақсаттың қаншалықты мәнсіз болғанын байқап, бақыт байлыққа ғана тірелмейтінін түсінеді. Бірақ осы сабақты меңгерсе де, Бубны бұрынғыдай ақшаны жақсы көреді және оны жұмсағанды ұнатады.","Пики":"Пики адамдары көбіне рухы күшті болады. Дәл оларды бүкіл «колодадағы» рухани тұрғыдан ең дамыған адамдар деп атауға болады. Айта кету керек, олар онша көп емес. Пики — еңбек, денсаулық және руханилық мастьі, — егде жас, қыс. Стихиясы — От, Тародағы Таяқтар (Жезлы) мастьі.\nПики мастьі идеяларды шындыққа айналдыру қажеттілігін бейнелейді. Осы мастьпен бейнеленген жоғары дамыған адамдар кәсіпкер, ұйымшыл және жалпы игілік үшін құрбандыққа баруға дайын. Пики басқа карталардан өзгеше әрекет етіп, өмір сүреді. Ерік күшінің арқасында олар Черви, Трефы және Бубны манипуляцияларына берілмей алады. Пики мастьінің аз дамыған тұлғалары күнделікті тірлік әбігеріне жиі батып, үнемі бір қатені қайталайды.\nПики — еңбегінің сапасына алаңдайтын еңбекқорлар, бұл оларды көбіне еңбек әкелетін табыстан да көбірек қызықтырады. Пики мастьінің әсерімен туған басшы қол астындағыларға ерекше қатаң әрі аяусыз болуы мүмкін, олардың да жұмысқа өзі сияқты күш салатынына есеп жасайды.\nПики даналық пен тәжірибені бейнелейді, олардың өмірге көзқарасы басқа адамдардың көпшілігіне қарағанда кемелірек. Біреу оларды бақылауға тырысқанда төзбейді, сондықтан айналадағы шындықтың мүмкіндігінше үлкен бөлігін бақылауға алуға ұмтылады. Бұлар мойымайтын ерік күші бар күшті адамдар, сондықтан бұл масттың көп өкілі жеке қарым-қатынаста да көшбасшылық мәселелерін шешуге мәжбүр. Олар осы саладағы ішкі қайшылығын шешпейінше, серіктесімен билік пен бақылау үшін күреседі.\nАлайда Пики жеткен биігінде тек басқа үш мастьпен байланысты қасиеттерді жақсы меңгерген жағдайда ғана тұра алады. Пики өкілі басқа масттың қандай да бір қырын дамытпаса, сол мастьқа сәйкес саладағы мәселелердің құрбаны болады. Мысалы, Пики жеке қарым-қатынаста жиі үлкен қиындықтарға тап болады. Бұл Пикидің черви мастьінен алыстығымен байланысты және Червимен байланысты өмір салаларының оларға белгілі бір дәрежеде жат болуына әкеледі. Көп Пики жақсы жұмыс пен парызды орындау қарым-қатынас пен эмоция саласынан маңыздырақ деп санайды. Бұл, әрине, Пикидің бақытты некеге тұра алмайтынын білдірмейді, жай ғана бұл масттың көп өкілі осы салада қиындықтарға кездеседі.\nПики мастьі адамға бойындағы бүкіл әлеуетті толық ашуға мүмкіндік береді. Бірақ ол үшін өз еркін тежеп, руханилыққа деген ықыласын тауып, түсіну үшін жұмыстан уақытша алаңдау қажет. Бұл жағдайда Пика рухани дамудың ең жоғары сатысына жете алады, бұл оның өзіне де, айналасындағы адамдарға да пайда әкеледі.","Крести":"Крести адамдары бұл әлемге білім үшін келген. Олар картоп немесе банан сата алмайды және, сірә, мұны ешқашан үйренбейді, бірақ өз білімін сата білуі керек. ♣ Трефы ♣\nТрефы — білім мен идеялар мастьі, — мектеп және студенттік жылдар, жаз. Стихиясы — Ауа, Тародағы Семсерлер (Мечи) мастьі.\nТрефы мастьінің басқаруымен туған адамдардың көпшілігі ұтымды, ақылды, ойлы және білуге құмар. Ішкі дауысына мұқият құлақ аса отырып, олар түйсік пен бірегей табиғи таланттарды дамыта алады. Зерек, өздерін қызықтыратын мәселелерге ынталы бұл адамдар басты қарулары — ақыл күші екенін түсінгенде табысқа жетеді. Олар білімді оңай меңгереді, ойларын шешен жеткізеді және пікірталас пен талқылауларға қуана қатысады. Оларды идеялар, араласу әдістері, өз ойлары мен көзқарастарының сапасы, сондай-ақ осы ойлар мен көзқарастардың арқасында әлемде із қалдыру мүмкіндігі қызықтырады.\nТрефы адамдарды сөзіне қарап бағалайды және сөзді байыпты қабылдайды. Ерте ме, кеш пе Трефы мастьі өкілдерінің көпшілігі күрделі мәселеге тап болады: адамдардың не айтатынын олардың шын мәнінде кім екенінен қалай ажыратуға болады? Трефының тағы бір ерекшелігі — олар көбіне жағдайды оған қатысушылардың сезімдерін ескермей бағалайды. Сонымен бірге олар жиі жағдайдың шынайы себебі болуы мүмкін өз эмоцияларын да ұмытады. Кейде Трефы фактілер мен шындықты асыра пайдалануы мүмкін. Мысалы, сіз абайсызда сеніп айтқан ақпаратты өзіңізге қарсы пайдалана алады.\nТрефы әдетте өздерін қызықтыратын жағдайдың барлық егжей-тегжейін анықтауға ұмтылады. Трефы мастьінің өкілімен некеге тұруды шешсеңіз, бұл ерекшелікті ұмытпаған жөн. Мұндай адам сізден өміріңіздің ең ұсақ егжей-тегжейін сұрастырады — сізге сенбегендіктен емес, жай ғана бұл оның басты қажеттіліктерінің бірі болғандықтан.\nКөп Трефы өмірінде тұлғаның еркіндігі мен тәуелсіздігіне қатысты мәселелерге тап болады. Олардың стихиясы — Ауаны бейнелейтін жел сияқты, олар қалаған кезде пайда болып, жоғалып кете алады. Бұл ерекшелік көбіне Трефыға тұрақты әрі ұзақ жеке қарым-қатынас құруға кедергі жасайды. Трефы мастьінің өкілдері өздерін қозғалмалы, өзгермелі сенімдерімен тым қатты теңестіреді, бұл бақытты некеге апарар жолда кедергі болуы мүмкін. Әрине, бұл осы масттың барлық өкіліне тән емес, бірақ олардың арасында жиі кездеседі.","Черви":"Черви адамдары бұл өмірде (инкарнацияда) сүюді және сүйікті болуды үйренуі керек. Олар да крести мен бубны адамдарынан аз, бірақ пики адамдарынан көп. Бірақ не істейміз, қазір осындай ғасыр — ақша мен білім ғасыры! Бұл жаман да, жақсы да емес, өйткені әрқайсымыздың шешуге тиіс өз міндеттеріміз бар, ал кейде мұны істеу оңай емес. Сондықтан басқаларға қызғанбай, барымызбен өмір сүріп, жұмыс істейік — оларға да оңай емес, тіпті біз мұны байқамасақ та. Черви — махаббат, романтика, махаббат қарым-қатынасы және көркем өзін-өзі білдіру мастьі, — балалық шақ, көктем. Стихиясы — Су, Тародағы Тостағандар (Кубки) мастьі.\nОсы масттың басқаруымен туған адамдар әсершіл және өте эмоциялы. Олар махаббат сыйлап, қолдау көрсете білуінің, түсіністік пен жанашырлық танытуының арқасында өмірлерін жақсартады. Зейінді әрі сезімтал бұл адамдар көбіне адал достар мен сүйетін серіктестер болады. Черви әйелдер мінсіз романтикалық сүйікті және жар бола алады.\nӘдетте Черви мастьімен байланысты адам белгілі бір уақытта бар назарын өзі үшін өмірдің мәніне айналатын балаға немесе романтикалық серіктеске шоғырландырады. Біраз уақыттан кейін бұл тұрақты ой тоқтап, адам өз тұлғасы мен айналадағы әлемнің арасында тепе-теңдік табады. Өз мастьімен байланысты салаларға терең бойлай отырып, ол өзін және ішкі болмысын жақсырақ түсінуге мүмкіндік алады. Көп Черви бүкіл өмірін көркем өзін-өзі білдіруге арнайды — бұл масттың өкілдерінің арасында белгілі актерлер, музыканттар мен суретшілер көп.\nЧерви мастьінің адамдары балаларына шамадан тыс қамқорлық жасап, оларды қысымға алып, махаббатын сау емес тәсілмен білдіруге бейім. Червидің өзін-өзі бағалау мәселелеріне ерекше көзқарасы бар. Олардың басты құралы — мақұлдау мен мойындау немесе олардың жоқтығы. Бұл масттың өкілі ата-аналар балаларына осы қасиетті беретіндей, адамдарға олардың бірегейлігі мен ерекшелігін мойындауды бере алады. Ал Черви біреуге ауырсыну келтіргісі немесе бізді бақылауға алғысы келгенде, оны осы мойындаудан айырады. Бұл — Черви жиі ұстанатын мінез-құлық үлгілері.\nЧерви мастьіне жататын адамдар эмоцияларын бағыттауды, екпінділікке және өзімшілдік, жек көрушілік немесе қызғаныш сияқты жағымсыз қасиеттерді оятуы мүмкін қорқыныштарға берілмеуді үйренуі керек."};
const JOKER = { card: "Joker", text: "Джокер" };

// Код даты (карта) по формуле 55 − (2 × месяц + день): 1 января = 52 (K♠), 30 декабря = 1 (A♥), 31 декабря = 0 (Джокер)
function dateCode(day, month) {
  return 55 - (2 * month + day);
}
function cardByCode(code) {
  return code === 0 ? JOKER : LOVE_CARDS[code];
}

function getBirthCardIndex(day, month) {
  return dateCode(day, month);
}

function getBirthCard(day, month) {
  const idx = getBirthCardIndex(day, month);
  const suit = BIRTH_CARD_SUIT[idx] || "";
  return {
    index: idx,
    card: cardByCode(idx).card,
    text: BIRTH_CARD_TEXTS[idx] || "",
    suit: suit,
    suitText: SUIT_TEXTS[suit] || "",
  };
}

// Персональная энергия каждого дня выбранного года: карта рождения + код даты, больше 52 — минус 52
function getYearForecast(day, month, year, targetYear) {
  const birthIdx = getBirthCardIndex(day, month);
  const rows = [];
  const start = Date.UTC(targetYear, 0, 1);
  const isLeap = (targetYear % 4 === 0 && targetYear % 100 !== 0) || targetYear % 400 === 0;
  const totalDays = isLeap ? 366 : 365;

  for (let i = 0; i < totalDays; i++) {
    const d = new Date(start + i * 86400000);
    let personalCode = birthIdx + dateCode(d.getUTCDate(), d.getUTCMonth() + 1);
    if (personalCode > 52) personalCode -= 52;
    const entry = cardByCode(personalCode);
    rows.push({
      date: String(d.getUTCDate()).padStart(2, "0") + "." + String(d.getUTCMonth() + 1).padStart(2, "0") + "." + targetYear,
      code: personalCode,
      card: entry.card,
      text: entry.text,
    });
  }
  return rows;
}

function getFullResult(day, month, year, name, targetYear) {
  const sy = targetYear || new Date().getFullYear();
  return {
    birthCard: getBirthCard(day, month),
    year: getYearForecast(day, month, year, sy),
  };
}


