const RELATION_TEXTS = {"0":"Джокер — еркіндік, ойын және бәріне жеңіл қарай білу. Қарым-қатынас өзіңді тым байыпты қабылдамауға және өзің болып қалуға үйретеді.","1":"Черви тұзы — жаңа махаббат, сүйікті болуға деген күшті тілек. Сабақ: өзіңді жақсы көру, сонда басқаның махаббаты құтқарылу іздеу болмайды.","2":"Черви екілігі — екі жүректің одағы, жақындық пен достық. Сабақ: нағыз серіктес болу, сезімдермен ашық бөлісу.","3":"Черви үштігі — сезімдердің әртүрлілігі және шешімсіздік. Сабақ: махаббатта шын мәнінде не қалайтыныңызды анықтап, екі ұшты болмау.","4":"Черви төрттігі — отбасы, неке, сезімдегі тұрақтылық. Сабақ: үй құрып, бір-біріңізге қамқорлық жасау, қамқорлықты бақылауға айналдырмау.","5":"Черви бестігі — сезімдердегі өзгерістер, жаңаны іздеу. Сабақ: бір-біріңізге еркіндік қалдыру және қарым-қатынастағы өзгерістерден қорықпау.","6":"Черви алтылығы — кармалық байланыс, бейбітшілік пен ымыра. Сабақ: махаббат қарызын қайтару, үйлесім үшін жол беру және кешіру.","7":"Черви жетілігі — рухани махаббат, қызғаныш пен қорқыныштан босау. Сабақ: шартсыз және иеленуге деген тілексіз сүю.","8":"Черви сегіздігі — жұптың эмоциялық күші мен сүйкімділігі. Сабақ: бір-біріңізге әсерді ұқыпты пайдалану — жаралау үшін емес, емдеу үшін.","9":"Черви тоғыздығы — аяқталу және жалпыға ортақ махаббат. Сабақ: ескіргенді өкпесіз жіберу және жеке махаббаттан кеңірек махаббатты үйрену.","10":"Черви ондығы — қоғамдағы сәттілік, мойындау, балалар. Сабақ: бірге қуану және жылуды айналадағылармен бөлісу.","11":"Черви валеті — құрбандыққа баратын махаббат. Сабақ: бір-біріңізге көмектесу, бірақ құтқарушы мен құрбанға айналмау.","12":"Черви дамасы — аналық қамқорлық, неке, жайлылық. Сабақ: бір-біріңізге қамқорлық жасау, жалқаулық пен еркелікке берілмеу.","13":"Черви королі — махаббат күші мен жауапкершілік. Сабақ: сезімдерді даналықпен басқару, бір-біріңізге сенімді тірек болу.","14":"Трефы тұзы — жаңа білім мен араласу. Сабақ: бірге оқу, идеялармен бөлісу және бір-біріңізді шабыттандыру.","15":"Трефы екілігі — әңгімелер, даулар, ой алмасу. Сабақ: сөйлесу және келісу, араласуды дауға айналдырмау.","16":"Трефы үштігі — шығармашылық пен мазасыз ақыл. Сабақ: алаңдаушылықты ортақ идеяларға айналдыру және бастаған істі соңына жеткізу.","17":"Трефы төрттігі — ақыл-ой тұрақтылығы мен тыныштық. Сабақ: бір-біріңізге сену және қырсықтықта тұрып қалмау.","18":"Трефы бестігі — өзгерістер, сапарлар, жаңа көзқарастар. Сабақ: қарым-қатынасқа қозғалыс беру, саяхаттау және ой-өрісті кеңейту.","19":"Трефы алтылығы — түйсік және сөзге жауапкершілік. Сабақ: уәдеде тұру және ішкі дауысқа құлақ асу.","20":"Трефы жетілігі — рухани білім және ой күші. Сабақ: жағымсыз ойлауды жағымдыға ауыстыру және бір-біріңізді қолдау.","21":"Трефы сегіздігі — ақыл күші мен мақсаткерлік. Сабақ: ортақ энергияны мақсатқа бағыттау және бір-біріңізге қысым жасамау.","22":"Трефы тоғыздығы — ескі көзқарастардың аяқталуы. Сабақ: ескірген сенімдерді жіберу және даналықпен бөлісу.","23":"Трефы ондығы — ақыл істеріндегі сәттілік, мойындау. Сабақ: бірге даму, жұмыстың артында сезімдерді ұмытпау.","24":"Трефы валеті — шығармашыл ақыл, идеялар. Сабақ: бір-біріңізге адал болу және сөзбен ойнамау.","25":"Трефы дамасы — түйсік, білім, қызмет ету. Сабақ: түйсікке сену және бір-біріңіздің дамуын қолдау.","26":"Трефы королі — даналық пен білім. Сабақ: бір-біріңіздің пікірін құрметтеу, бірге оқу және үйрету.","27":"Бубны тұзы — жаңа ақша мен тілектер. Сабақ: махаббатты пайдадан ажырату және бірге айқын мақсаттар қою.","28":"Бубны екілігі — іскерлік серіктестік. Сабақ: адал ынтымақтасу, бірге табыс табу және ақша туралы келісу.","29":"Бубны үштігі — қаржыдағы шығармашылық және құндылықтарды іздеу. Сабақ: сіз үшін не шынымен құнды екенін түсіну және жетіспеушіліктен қорқып өмір сүрмеу.","30":"Бубны төрттігі — материалдық тұрақтылық. Сабақ: бірге еңбек ету және отбасына сенімді негіз жасау.","31":"Бубны бестігі — құндылықтар мен қаржыдағы өзгерістер. Сабақ: өзгерістерді қабылдау және кеткенге жабыспау.","32":"Бубны алтылығы — қаржылық карма мен жауапкершілік. Сабақ: ақшада адал болу, қарызды қайтару және артығын алмау.","33":"Бубны жетілігі — ақшаға рухани көзқарас. Сабақ: өмірге сену, ақша туралы уайымдамау және алғыс айту.","34":"Бубны сегіздігі — күш, сәттілік, материалдық билік. Сабақ: бір-біріңізді басып тастамай, мақсатқа бірге жету.","35":"Бубны тоғыздығы — жомарттық пен шығындар. Сабақ: оңай беру, бөлісу және материалдыққа жабыспау.","36":"Бубны ондығы — молшылық пен үлкен ақша. Сабақ: әл-ауқатты бірге көбейту және ақшаны басты мақсат етпеу.","37":"Бубны валеті — кәсіпкерлік, сауда, идеялар. Сабақ: сөзде тұру және ортақ істерде адал болу.","38":"Бубны дамасы — жомарттық, әдемі өмірге деген махаббат. Сабақ: шамаға қарай өмір сүру және бір-біріңізді ақылмен еркелету.","39":"Бубны королі — бизнестегі сәттілік пен билік. Сабақ: бір-біріңіздің пікірін құрметтей отырып, ортақ іс құру.","40":"Пики тұзы — құпиялар, түрлену, терең өзгерістер. Сабақ: өзгерістерден бірге өтіп, рухани өсу.","41":"Пики екілігі — достық және жұмыс серіктестігі. Сабақ: істерде дос және сенімді одақтас болу.","42":"Пики үштігі — күйзеліс (стресс) және бірден бірнеше бағытта жұмыс. Сабақ: бір-біріңіздің күшіңізді аялау және шашыраңқы болмау.","43":"Пики төрттігі — еңбектен қанағат пен тұрақтылық. Сабақ: бірге көп жұмыс істеу және нәтижеге қуану.","44":"Пики бестігі — көшу, саяхат, өзгерістер. Сабақ: икемді болу және орынды да, өмір салтын да өзгертуден қорықпау.","45":"Пики алтылығы — тағдыр және кармалық жауапкершілік. Сабақ: өз қылықтарыңызға жауап беру және бәрі өзінен-өзі шешіледі деп күтпеу.","46":"Пики жетілігі — сынақтар мен рухани жеңіс. Сабақ: қиындықтарды сеніммен жеңу, денсаулықты сақтау және пессимизмге берілмеу.","47":"Пики сегіздігі — жұмыстағы күш пен сәттілік. Сабақ: ортақ күшті игілікке бағыттау және бір-біріңізбен билік үшін күреспеу.","48":"Пики тоғыздығы — үлкен аяқталулар. Сабақ: аяқталуды жаңа кезеңнің басы ретінде қабылдау және өзгерістерде бір-біріңізді қолдау.","49":"Пики ондығы — ауыр әрі табысты еңбек, үлкен жетістіктер. Сабақ: ортақ мақсат үстінде бірге жұмыс істеу — мұндай одақтың қолынан көп нәрсе келеді.","50":"Пики валеті — шығармашылық және даналыққа бағыштау. Сабақ: адал болу және рухани даму.","51":"Пики дамасы — өзін-өзі бақылау және шеберлік. Сабақ: өзіңізді, эмоцияларыңызды басқару және өмірде бірге тәртіп орнату.","52":"Пики королі — жоғары билік пен даналық. Сабақ: ортақ күшті даналықпен пайдалану және өміріңіз үшін жауапкершілік алу."};

function reduce52(n) {
  while (n > 52) n -= 52;
  return n;
}
function cardLabel(code) {
  return cardByCode(code).card;
}
function getRelationship(day1, month1, day2, month2) {
  const a = getBirthCardIndex(day1, month1);
  const b = getBirthCardIndex(day2, month2);
  const common = reduce52(a + b);
  const lesson1 = reduce52(common + a);
  const lesson2 = reduce52(common + b);
  const item = (code) => ({ code, card: cardLabel(code), text: RELATION_TEXTS[code] || "" });
  return { card1: item(a), card2: item(b), common: item(common), lesson1: item(lesson1), lesson2: item(lesson2) };
}

window.LoveCardsEngine = { getFullResult, getBirthCard, getYearForecast, getBirthCardIndex, dateCode, getRelationship };
